// Command CrackedApiReference-cli is a CLI + REPL for the CrackedApiReference SDK,
// built on the boru engine. Positional arguments are joined into a
// single boru expression and evaluated; with no arguments, falls into
// a REPL. Generated by sdkgen go-cli target.
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"

	eng "github.com/boru-lang/boru/eng/go"
	"github.com/boru-lang/boru/eng/go/parser"
	sdk "github.com/voxgig-sdk/cracked-api-reference-sdk/go"
)

// prompt is the REPL prompt prefix (matches the SDK slug).
const prompt = "cracked-api-reference"

// entitiesHelp is the space-separated entity list shown by /help.
const entitiesHelp = "activate activate_user active_onboarding admin admin_account_reset admin_carousel admin_carousel_demo_review admin_customer admin_customer_success admin_generated_video admin_healthrx admin_insight admin_landing_task admin_metrics_summary admin_post admin_recent_signup admin_slideshow_diag admin_slideshow_import admin_user_view admin_users_table_item admin_video_remixer advance_step agent agent_access_customers_health agent_access_overview agent_access_phil_hourly_notification agent_access_phil_stats_refresh agent_access_phil_video agent_access_user_agent agent_access_user_phone_farm agent_access_user_post agent_access_user_summary agent_access_user_video agent_access_user_winning_ad agent_access_winning_ads_summary agent_detail agent_health agent_health_customer_option agent_health_detail agent_post agent_stat agent_summary agents_summary analysis_status analytics_post analyze_product assign_agent auth auto_schedule_setting bulk_tik_tok_stats_update carousel carousel_agent_detail carousel_status chat chat_history chat_session comment comment_campaign complete_chat_checkout create_blackout_sora2_video create_carousel create_product create_reset_product_v6 create_sora2_video create_variation customer customer_health customer_health_all_customers_item customer_health_views_summary daily daily_status dedicated_agents_dashboard enterprise_agent enterprise_product exact_availability exact_formula extract_v2 failed_post file generate_blackout_sora2_prompt generate_pomelli_demo generate_prompt generate_sora2_prompt healthrx init_reset_product_v6 iri iris_capability iris_chat iris_connector iris_status iris_task iris_usage landing landing_stat landing_status link_in_bio link_in_dm link_in_post link_user media_asset men microdrama microhub_public onboarding_status onboarding_v6 paid_user pexel phone_admin_available_agent_source product product_dashboard product_dashboard_view product_demo product_landing public_resume_status re_roll_video read_root_get record_demo_booked refresh_stat remixer_clipper reset_product retry_website_scrape save_survey scan_social scan_socials_public scan_socials_status schedule_v2 scrape scrape_website_public scraped_data scraping_status self_serve_activate seo seo_ai_mention seo_backlink seo_keyword seo_overview seo_traffic share_access_link site slide slug_validation social social_scan_preview social_scan_process social_scan_save sora2_avatar sora2_avatar_asset_upload sora2_avatar_stat stat stats_refresh_backfill stats_refresh_issue stats_refresh_overview stats_refresh_run_summary stats_refresh_task_trigger stripe style template tik_tok_creator_info top_post upload_post_agent user user_agent user_health_detail user_with_avatar_submission users_health video video_remixer_worker watchdog_recovery winning_ad x_adaptation zerohuman_admin_account"

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

// usage prints the CLI help (for --help / -h). No client or network setup.
func usage(out io.Writer) {
	fmt.Fprintf(out, "%s-cli — boru-driven CLI + REPL for the %s SDK\n\n", prompt, prompt)
	fmt.Fprintln(out, "Usage:")
	fmt.Fprintf(out, "  %s-cli [--help] [<boru expression>]\n\n", prompt)
	fmt.Fprintln(out, "With arguments, they are joined into a single boru expression and")
	fmt.Fprintln(out, "evaluated against the API. With no arguments, starts an interactive REPL.")
	fmt.Fprintln(out)
	fmt.Fprintln(out, "Words:    list / load / update <query?> <entity>")
	fmt.Fprintln(out, "Entities:", entitiesHelp)
	fmt.Fprintln(out, "Env:      CRACKED_API_REFERENCE_APIKEY (api key), CRACKED_API_REFERENCE_BASE (base url override)")
	fmt.Fprintln(out, "REPL:     /help  /quit")
}

func run(args []string, in io.Reader, out, errOut io.Writer) int {
	// --help / -h: print usage and exit before any config or network setup.
	for _, a := range args {
		if a == "--help" || a == "-h" {
			usage(out)
			return 0
		}
	}

	// Configure from the environment: CRACKED_API_REFERENCE_APIKEY carries the API key and
	// CRACKED_API_REFERENCE_BASE optionally overrides the API base URL (e.g. production).
	// Both injectable by a secrets vault. Unset -> nil config defaults.
	var opts map[string]any
	if apikey := os.Getenv("CRACKED_API_REFERENCE_APIKEY"); apikey != "" {
		opts = map[string]any{"apikey": apikey}
	}
	if base := os.Getenv("CRACKED_API_REFERENCE_BASE"); base != "" {
		if opts == nil {
			opts = map[string]any{}
		}
		opts["base"] = base
	}
	client := sdk.NewCrackedApiReferenceSDK(opts)

	r, err := eng.NewRegistry()
	if err != nil {
		fmt.Fprintf(errOut, "registry: %v\n", err)
		return 1
	}
	registerSDKWords(r, client)
	if err := r.Err(); err != nil {
		fmt.Fprintf(errOut, "word registration: %v\n", err)
		return 1
	}
	r.SetParseFunc(parser.Parse)
	r.InitRootContext()
	r.MarkReady()

	if len(args) > 0 {
		return evalOnce(r, strings.Join(args, " "), out, errOut)
	}
	repl(r, in, out)
	return 0
}

func evalOnce(r *eng.Registry, src string, out, errOut io.Writer) int {
	values, err := parser.Parse(src)
	if err != nil {
		fmt.Fprintf(errOut, "parse: %v\n", err)
		return 1
	}
	result, err := eng.NewTop(r).Run(values)
	if err != nil {
		fmt.Fprintf(errOut, "error: %v\n", err)
		return 1
	}
	for _, v := range result {
		fmt.Fprintln(out, v.String())
	}
	return 0
}

func repl(r *eng.Registry, in io.Reader, out io.Writer) {
	scanner := bufio.NewScanner(in)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	for {
		fmt.Fprintf(out, "%s> ", prompt)
		if !scanner.Scan() {
			fmt.Fprintln(out)
			return
		}
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		switch line {
		case "/quit", "/q", "/exit":
			return
		case "/help", "/h", "/?":
			fmt.Fprintln(out, "words:    list / load / update <query?> <entity>")
			fmt.Fprintln(out, "entities:", entitiesHelp)
			fmt.Fprintln(out, "meta:     /help  /quit")
			continue
		}
		values, err := parser.Parse(line)
		if err != nil {
			fmt.Fprintf(out, "  parse error: %v\n", err)
			continue
		}
		result, err := eng.NewTop(r).Run(values)
		if err != nil {
			fmt.Fprintf(out, "  error: %v\n", err)
			continue
		}
		for _, v := range result {
			fmt.Fprintln(out, v.String())
		}
	}
}
